@startuml

class Museum {
  + name : string
  + location : string
}

class Location {
  + roomNumber : string
  + floor : int
  + wing : string
}

class Exhibition {
  + title : string
  + openingDate : date
  + planningStartDate : date
  + status : string
}

class Employee {
  + employeeID : int
  + name : string
  + role : string
}

class ExhibitionItem {
  + description : string
  + period : string
}

class Piece {
  + title : string
  + artist : string
  + dimensions : string
}

class Collector {
  + collectorID : int
  + name : string
  + contactInfo : string
}

class Request {
  + requestDate : date
  + status : string
}

Museum "1" *-- "1..*" Location
Location "1" -- "0..*" Exhibition
Exhibition "1" -- "1" Employee : coordinatedBy
Exhibition "1" -- "1..*" ExhibitionItem : contains
ExhibitionItem "1" -- "0..*" Request
Request "1" -- "1" Piece : forPiece
Request "1" -- "1" Collector : requestedFrom
Employee "1" -- "0..1" Employee : coachedBy
Employee "1" -- "0..*" Employee : coaches

@enduml

